from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee name -> dict of year -> set of dates taken as leave
        self.employee_leaves: dict[str, dict[int, set[date]]] = defaultdict(lambda: defaultdict(set))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        # A request made less than 3 days before its start date is rejected
        if start - today < timedelta(days=3):
            raise ValueError("Leave requests must be made at least 3 days in advance.")

        # Determine all candidate leave days (weekdays not in holidays)
        leave_days_by_year: dict[int, list[date]] = defaultdict(list)
        current = start
        while current <= end:
            # Monday is 0, Sunday is 6; weekday < 5 means Monday through Friday
            if current.weekday() < 5 and current not in self.holidays:
                leave_days_by_year[current.year].append(current)
            current += timedelta(days=1)

        # Check that the employee has enough remaining leave days in each relevant year
        # Also accounts for previously booked days if re-requested (avoids double counting)
        for year, days in leave_days_by_year.items():
            existing_days = self.employee_leaves[employee][year]
            new_days = [d for d in days if d not in existing_days]
            rem = self.remaining(employee, year)
            if len(new_days) > rem:
                raise ValueError(
                    f"Insufficient leave balance for {employee} in year {year}: "
                    f"requested {len(new_days)} days, {rem} remaining."
                )

        # Record the leave days
        total_used = 0
        for year, days in leave_days_by_year.items():
            for d in days:
                if d not in self.employee_leaves[employee][year]:
                    self.employee_leaves[employee][year].add(d)
                    total_used += 1

        return total_used

    def remaining(self, employee: str, year: int) -> int:
        """Returns the number of unused leave days remaining for an employee in a given year."""
        used = len(self.employee_leaves[employee][year])
        return max(0, self.days_per_year - used)
